  "sources": ["/files/GitHub/dev/pretext/css/targets/print-worksheet.scss", "/files/GitHub/dev/pretext/css/targets/../../fonts/_fonts-google.scss", "/files/GitHub/dev/pretext/css/targets/../../components/chunks/_asides-basic.scss", "/files/GitHub/dev/pretext/css/targets/../../components/chunks/_asides-floating.scss", "/files/GitHub/dev/pretext/css/targets/../../components/chunks/_codelike.scss", "/files/GitHub/dev/pretext/css/targets/../../components/helpers/_cols.scss", "/files/GitHub/dev/pretext/css/targets/../../components/chunks/_exercises.scss", "/files/GitHub/dev/pretext/css/targets/../../components/chunks/_solutions.scss", "/files/GitHub/dev/pretext/css/targets/../../components/chunks/_sidebyside.scss", "/files/GitHub/dev/pretext/css/targets/../../components/chunks/helpers/_inline-heading-mixin.scss", "/files/GitHub/dev/pretext/css/targets/../../components/chunks/_discussion-inline.scss", "/files/GitHub/dev/pretext/css/targets/../../components/chunks/_knowls.scss", "/files/GitHub/dev/pretext/css/targets/_chunks-worksheet.scss", "/files/GitHub/dev/pretext/css/targets/../../components/_spacing.scss", "/files/GitHub/dev/pretext/css/targets/../../components/elements/_list-styles.scss", "/files/GitHub/dev/pretext/css/targets/../../components/elements/_description-lists.scss", "/files/GitHub/dev/pretext/css/targets/../../components/elements/_lists.scss", "/files/GitHub/dev/pretext/css/targets/../../components/elements/_fillin.scss", "/files/GitHub/dev/pretext/css/targets/../../components/elements/_headings.scss", "/files/GitHub/dev/pretext/css/targets/../../components/elements/_links.scss", "/files/GitHub/dev/pretext/css/targets/../../components/elements/_tables.scss", "/files/GitHub/dev/pretext/css/targets/../../components/elements/_front-matter.scss", "/files/GitHub/dev/pretext/css/targets/../../components/elements/_summary-links.scss", "/files/GitHub/dev/pretext/css/targets/../../components/elements/_footnotes.scss", "/files/GitHub/dev/pretext/css/targets/../../components/elements/_index.scss", "/files/GitHub/dev/pretext/css/targets/../../components/elements/_media.scss", "/files/GitHub/dev/pretext/css/targets/../../components/elements/_figures.scss", "/files/GitHub/dev/pretext/css/targets/../../components/elements/_poem.scss", "/files/GitHub/dev/pretext/css/targets/../../components/elements/_prism.scss", "/files/GitHub/dev/pretext/css/targets/../../components/elements/_math.scss", "/files/GitHub/dev/pretext/css/targets/../../components/elements/_permalinks.scss", "/files/GitHub/dev/pretext/css/targets/../../components/elements/_misc-content.scss", "/files/GitHub/dev/pretext/css/targets/../../components/_printing.scss", "/files/GitHub/dev/pretext/css/targets/../../components/_worksheet.scss", "/files/GitHub/dev/pretext/css/targets/../../components/_google-search.scss", "/files/GitHub/dev/pretext/css/targets/../../components/_pretext-search.scss", "/files/GitHub/dev/pretext/css/targets/../../components/helpers/_buttons-default.scss", "/files/GitHub/dev/pretext/css/targets/../../components/interactives/_runestone.scss", "/files/GitHub/dev/pretext/css/targets/../../components/interactives/_webwork.scss", "/files/GitHub/dev/pretext/css/targets/../../components/interactives/_sagecell.scss", "/files/GitHub/dev/pretext/css/targets/../../components/interactives/_calculators.scss", "/files/GitHub/dev/pretext/css/targets/../../colors/_color-vars.scss", "/files/GitHub/dev/pretext/css/targets/../../colors/_color-helpers.scss"],
  "sourcesContent": ["/*! Theme: print-worksheet */\n\n// Used for print versions of worksheets (including their previews) for all themes\n\n// File is only included in standalone printable worksheet pages (the print preview pages).\n// Most rules apply to both screen and print; rules at the bottom of the file split into these two cases.\n\n// Also see:\n// components/_printing.scss : base rules for printing a standard PreTeXt page - removes UI\n// components/_worksheet.scss : rules that apply to worksheets in context and in print/preview.\n\n// Current maintainer: Oscar Levin\n\n// ---------------------------------------------\n// Grouping containers - based off of those in default-modern\n@use 'chunks-worksheet' with ($border-radius: 0);\n\n// Bring in the standard PreTeXt styles for components\n@use 'components/pretext';\n\n// Use underline style headings\n//@use 'components/elements/extras/heading-underlines';\n\n// Make sure fonts are available\n@use 'fonts/fonts-google';\n\n// For the print button\n@use 'components/helpers/buttons-default' as buttons;\n\n\n// Make sure we are including the root colors using simple black-and-white palette\n@use \"colors/color-helpers\" as colorHelpers;\n@use 'colors/palette-single' as palette with (\n  $primary-color: black,\n);\n\n// render the actual colors\n@include colorHelpers.set-root-colors(palette.$colors);\n\n// ---------------------------------------------\n// concrete rules / includes that generate CSS\n\n// Set variables for default width and margins\n:root {\n  --ws-width: 8.5in; // Default width for worksheets\n  --ws-height: 11in; // Default height for worksheets\n  --ws-top-margin: 40px; // Default top margin for worksheets\n  --ws-right-margin: 55px; // Default right margin for worksheets\n  --ws-bottom-margin: 45px; // Default bottom margin for worksheets\n  --ws-left-margin: 45px; // Default left margin for worksheets\n\n  --ws-content-width: calc(var(--ws-width) - var(--ws-right-margin) - var(--ws-left-margin));\n  --ws-content-height: calc(var(--ws-height) - var(--ws-top-margin) - var(--ws-bottom-margin));\n}\n\n\n\n\n// Remove surrounding UI elements\n  .pretext .ptx-masthead,\n  .pretext .ptx-navbar,\n  body.pretext > a.assistive,\n  .pretext .ptx-page > .ptx-sidebar,\n  .pretext  .ptx-page-footer,\n  .pretext .ptx-main > div.ptx-content-footer {\n    display:none;\n  }\n\n  // Remove the print preview link\n.heading .print-links {\n  display: none;\n}\n\n .autopermalink {\n  display: none;\n}\n\n// Some elements don't make sense to print:\n//   image descriptions\n//   webwork \"activate\" buttons\n//   buttons in general (to remove Runestone \"Check Me\" button)\n// We remove these here.\ndetails.image-description,\n.ptx-content .webwork-button,\n.ptx-runestone-container button.btn {\n  display: none;\n}\n\n\n// Set font appropriate for printing\nsection.worksheet, section.handout {\n  font-size: 11pt;\n  font-family: var(--font-print);\n}\n\n// .onepage is the common class that wraps all content in a single worksheet page (often modified by the javascript)\n .onepage > .heading {\n  margin-top: 0;\n  font-size: 1.3em;\n}\n\n.onepage .instructions {\n  display: none;\n}\n\n\n// Try to make an open solution knowl look less strange.  Eventually the print version of worksheets should create HTML that isn't a details element.\nsummary::marker {\n  content: \"\";\n}\n\nsummary {\n  font-weight: bolder;\n  display: inline;\n}\n\n.knowl__content {\n  display: inline;\n  margin: unset;\n  border: none;\n  padding: 3px 0;\n  background-color: unset;\n}\n\n.knowl__link {\n  all: unset\n}\n\n.code-inline {\n  border: unset;\n  background: unset;\n}\n\n.onepage article {\n  padding-left: 0;\n  border: none;\n}\n\n.onepage article::after {\n  all: unset;\n}\n\n.onepage > .para:first-child,\n.onepage > article:first-child {\n  margin-top: 0;\n}\n\n\n// Some headings have larger top-margins than their parent section, so we fix that here.\n.onepage > section > .heading {\n  margin-top: 0;\n}\n\n// tasks might be \"free-floating\" articles, in which case they should get the same indenting as tasks inside exercises.\n section article.task {\n  margin-left: 20px;\n}\n\nsection.worksheet > .heading, section.handout > .heading {\n  display: inline;\n  font-size: 1.1em;\n}\n\nsection.worksheet > .heading + .para, section.handout > .heading + .para {\n  display: inline;\n}\n\n.introduction, .conclusion {\n  > .heading {\n    font-size: 1.1em;\n    font-weight: bold;\n    margin-bottom: 0;\n    border-bottom: none;\n    + .para {\n      margin-top: 0.5em;\n    }\n  }\n}\n\nform.papersize-select {\n  padding-bottom: 8px;\n}\n\n\n\n\n// Screen specific styles (mostly for showing the border around a worksheet with it's \"margins\" and for the print controls)\n@media screen {\n  .ptx-main {\n    max-width: var(--ws-width);\n    margin: 50px auto;\n  }\n\n  .worksheet, .handout {\n    max-width: var(--ws-width);\n    margin: 0 auto;\n  }\n\n  .onepage {\n    width: 100%;\n    height: var(--ws-height);\n    padding: var(--ws-top-margin) var(--ws-right-margin) var(--ws-bottom-margin) var(--ws-left-margin);\n    box-shadow: 5px 10px 40px -10px;\n  }\n\n  // Set space between pages\n  .onepage + .onepage {\n    margin-top: 2.5em;\n  }\n\n\n  .workspace-container {\n    display: flex;\n    overflow: visible;\n  }\n\n  .workspace {\n    width: 100%;\n  }\n\n  .highlight-workspace .onepage .workspace {\n    border: 1px dashed grey;\n    background: hsl(224, 100%, 95%);\n  }\n\n  // Normally, the .workspace.original is hidden in the print preview, but if the highlight-workspace checkbox is checked, it will be shown.\n  .onepage .original-workspace {\n    display: none;\n  }\n\n  .highlight-workspace .onepage .original-workspace {\n    display:block;\n    width: 10px;\n    background: hsl(152, 29%, 65%);\n  }\n\n  .highlight-workspace .onepage .warning {\n    background: hsl(36, 65%, 67%);\n  }\n\n  .print-button {\n  @include buttons.ptx-button;\n  }\n\n  .papersize-select {\n    z-index: 1;\n    .name::after {\n      content: \": \";\n    }\n  }\n\n  .print-controls {\n    display: flex;\n    justify-content: space-between;\n    align-items: center;\n    padding-bottom: 1em;\n  }\n}\n\n\n\n// Print specific styles\n@media print {\n  body {\n    margin: 0;\n    padding: 0;\n    width: var(--ws-content-width);\n  }\n\n  .print-preview-header {\n    display: none;\n  }\n\n  section.worksheet, section.handout {\n    border: none;\n    width: 100%;\n\n    .onepage {\n      margin-top: 0;\n      width: 100%;\n      height: var(--ws-content-height);\n      overflow: hidden;\n      page-break-after: always;\n      page-break-inside: avoid;\n    }\n    // Never show the workspace preview in print\n    div.workspace,\n    div.workspace.squashed.tight {\n      border: none;\n      padding: 0;\n      background: none !important;\n    }\n  }\n\n  a {\n    color: black;\n  }\n\n  @page {\n    // Note: when we allow custom margins, the javascript will need to change these defaults.\n    // Default margins appear to be necessary for Firefox and Safari (Chrome already works with the variable values).\n    margin: var(--ws-top-margin, 40px) var(--ws-right-margin, 55px) var(--ws-bottom-margin, 45px) var(--ws-left-margin, 45px);\n  }\n}\n", "@use \"sass:map\";\n@use \"sass:string\";\n@use \"sass:list\";\n\n// Fonts to use\n$body: 'Open Sans, Helvetica Neue, Helvetica, Arial, sans-serif' !default;\n$heading: 'PT Serif, Times New Roman, Times, serif' !default;\n$monospace: 'Inconsolata, Consolas, Monaco, monospace;' !default;\n$print: 'PT Serif, Times New Roman, Times, serif' !default;\n\n@function is-variable-font($font-name) {\n  $static-fonts: ('PT Serif');  // list of known static fonts used by themes\n  @if list.index($font-name, $static-fonts) {\n    @return false;\n  }\n  @return true;\n}\n\n@function generate-import($font-name) {\n  @if is-variable-font($font-name) {\n    @return 'https://fonts.googleapis.com/css2?family=' + $font-name + ':ital,wght@0,400..700;1,400..700&display=swap';\n  }\n  @else {\n    @return 'https://fonts.googleapis.com/css2?family=' + $font-name + ':ital,wght@0,400;0,700;1,400;1,700&display=swap';\n  }\n}\n\n// For now, only try to fetch the first name in the list and assume\n// the rest are system defined fallbacks.\n// lists are 1-indexed\n$body-font: list.nth(string.split($body, ','), 1);\n// @debug \"----------------\" $body-font;\n@import url( generate-import($body-font) );\n\n$heading-font: list.nth(string.split($heading, ','), 1);\n// generate-import($heading-font);\n@import url( generate-import($heading-font) );\n\n$monospace-font: list.nth(string.split($monospace, ','), 1);\n// generate-import($monospace-font);\n@import url( generate-import($monospace-font) );\n\n:root {\n  --font-body: #{$body};\n}\n:root {\n  --font-headings: #{$heading};\n}\n:root {\n  --font-monospace: #{$monospace};\n}\n:root {\n  --font-print: #{$print};\n}\n\n// 9/5/24 ... TODO controlled list of fonts ... wait and explore later\n// // Available fonts\n// $serif-options: ('Alegreya', 'Merriweather', 'Noto Serif', 'PT Serif', 'Source Serif 4');\n// $sans-options: ('Alegreya Sans', 'Barlow', 'Lato', 'Open Sans', 'Roboto', 'Source Sans 3');\n// $code-options: ('Inconsolata');\n\n// // Backup lists\n// $sans-backups: ', Helvetica Neue, Helvetica, Arial, sans-serif';\n// $serif-backups: ', Times New Roman, Times, serif';\n\n// // ---------------------------------------------------------\n\n\n// @function add-fonts($list, $backups, $fonts: ()) {\n//   @each $font in $list {\n//     $fonts: map.set($fonts, $font, (\n//       url: '\"https://fonts.googleapis.com/css2?family=#{$font}:wdth,wght@75..100,300..800&amp;display=swap\"',\n//       fontlist: $font + $backups,\n//     ));\n//   }\n//   @return $fonts;\n// }\n\n// $fonts: add-fonts($sans-options, $sans-backups);\n// $fonts: add-fonts($serif-options, $sans-backups, $fonts);\n\n// $bodyfont: map.get($fonts, $body);\n// @if not $bodyfont {\n//   @error \"Unknown body font: #{$body}\";\n// } @else {\n//   @import url(#{map.get($bodyfont, \"url\")});\n//   :root {\n//     --font-body: #{map.get($bodyfont, \"fontlist\")};\n//   }\n// }\n\n// $headingfont: map.get($fonts, $heading);\n// @if not $headingfont {\n//   @error \"Unknown heading font: #{$heading}\";\n// } @else {\n//   @import url(#{map.get($headingfont, \"url\")});\n//   :root {\n//     --font-headings: #{map.get($headingfont, \"fontlist\")};\n//   }\n// }\n", "$border-width: 2px !default;\n$side-margins: 30px !default;\n\n.aside-like {\n  & > .knowl__link {\n    color: var(--aside-like-link-color);\n    border-bottom-color: var(--aside-like-link-color);\n  }\n  & > .knowl__content{\n    margin-left: $side-margins;\n    margin-right: $side-margins;\n    border: $border-width solid var(--aside-like-border-color);\n    background-color: var(--aside-like-body-background);\n  }\n}", "$float-width: 200px !default;\n$float-offset: -248px !default;\n$min-float-width: 1280px !default;\n\n@use 'asides-basic';\n\n@media screen and (min-width: $min-float-width) {\n  details.aside-like {\n    position: relative;\n    margin-left: $float-offset;\n    width: $float-width;\n    right: $float-offset;\n    float: right;\n    clear: right;\n  }\n\n  /* disable in any multicolumn list/exercisegroup */\n  .multicolumn details.aside-like {\n    position: relative;\n    margin-left: inherit;\n    width: auto;\n    right: 0;\n    float: none;\n    clear: none;\n  }\n\n  details.aside-like > .knowl__content {\n    margin-left:0;\n    margin-right:0;\n    background-color: var(--aside-like-body-background);\n    z-index: 100;\n  }\n}", "@mixin code-text {\n  font-family: var(--font-monospace);\n  background: var(--code-background);\n  font-size: .93rem;\n  line-height: 1.2;\n}\n\n@mixin code-inline-spacing {\n  line-height: normal;  //prevent extra \"padding\" based on line-height\n  padding: 0.0625em .15em;\n}\n\n// wide programs need to be scrollable\n.code-box {\n  overflow-x: auto;\n}\n\n.code-display {\n  overflow-x: auto;      //scroll if overflowing\n  font-family: var(--font-monospace);\n}\n\n.console,\n.program {\n  border: 1px solid var(--page-border-color);\n  padding: 5px 15px;\n  overflow-x: auto;\n  margin: 0;\n  @include code-text();\n}\n\n.code-inline {\n  font-family: var(--font-monospace);\n  white-space: pre;\n  color: var(--body-text-color);\n  background: var(--code-inline-background);\n  border: 1px solid color-mix(in oklab, var(--code-inline-background) 50%, #888);\n  border-radius: 0.2em;\n  display: inline-block;\n  overflow-x: auto;\n  max-width: 100%;\n  vertical-align: middle;\n  @include code-inline-spacing();\n}\n\n\n.prompt.unselectable {\n  user-select: none;\n}\n\n// code blocks are preformatted text that is not a program\n.code-block {\n  border-left: 1px solid #aaa;\n  padding: 0 15px 5px;\n  overflow-x: auto;\n  background: var(--code-background);\n  margin-top: 0;\n  margin-bottom: 0;\n  @include code-text();\n}\n\n.code-block::before {\n  content:' ';\n  font-size: 50%;\n  border-top: 1px solid #aaa;\n  display: block;\n  margin-right: auto;\n  margin-left: -15px;\n  width: 3.0em;\n}\n\n// special handling for code-display as it appears inside .paras\n// and may need space around it\n.code-display {\n  margin: 0.5em 0;\n}\n// if inside clipboardable, move margin to that container and turn some into padding\n// to help make sure clipboard icon is contained inside the code-display in dark mode\n.clipboardable:has(.code-display) {\n  margin: 0.25em 0;\n\n  .code-display {\n    margin: 0;\n    padding: 0.25em 0;\n  }\n}\n\n\n.clipboardable {\n  position: relative;  // To anchor the code-copy button\n  display: flow-root;\n\n  .code-copy {\n    position: absolute;\n    right: 0;\n    top: 0;\n    opacity: 0.25;\n    border-width: 0;\n    background: none;\n    cursor: pointer;\n    z-index: 1;\n    white-space-collapse: collapse;\n    padding: 1px;\n    scale: 0.85;\n\n    &:hover {\n      opacity: 0.7;\n    }\n\n    .checkmark {\n      display: none;\n    }\n\n    &.copied {\n      opacity: 1;\n      color: mediumseagreen;\n      cursor: not-allowed;\n      pointer-events: none;\n\n      .copyicon {\n        display: none;\n      }\n\n      .checkmark {\n        display: inline;\n      }\n    }\n  }\n}\n\n@media print {\n  .code-copy {\n    display: none;\n  }\n}\n", "\n// columns are arranged in row-major order to match print output in LaTeX\n:is(.cols2, .cols3, .cols4, .cols5, .cols6) {\n  display: flex;\n  flex-wrap: wrap;\n  justify-content: start;\n}\n\n// see lists and exercises for sample use\n@mixin allow-cols($el, $col-gap: 2em) {\n  @for $i from 2 through 6 {\n    .cols#{$i} > #{$el} {\n      // columns are a suggestion enforced by a minimum size\n      // content that needs to be wider can reduce number of columns\n      // in its row\n      min-width: calc(100% / $i - #{$col-gap});\n      width: min-content;\n      margin-right: $col-gap;\n    }\n  }\n}\n\n", "@use '../helpers/cols';\n\n// generate multi column rules for exercises\n@include cols.allow-cols('.exercise-like');\n\n.exercise-like > .heading {\n  // exercise heading/numbers regular size\n  font-size: inherit;\n}\n\n.exercisegroup {\n\n  .exercise-like {\n    margin-top: 1em;\n  }\n\n  > .heading {\n    font-size: 1.10em;\n    line-height: 1.05em;\n    margin-top: 0.75em;\n    display: inline;\n\n    & + .introduction {\n      display: inline;\n\n      & > .para:first-child {\n        display: inline;\n      }\n    }\n  }\n\n  // push the actual exercises down from any possible heading/intro\n  .exercisegroup-exercises {\n    margin-top: 1em;\n  \n    //indent items with padding so cols works correctly on them\n    padding-left: 40px;\n  }\n\n  .conclusion {\n    margin-left: 40px;  // match the padding of the exercisegroup-exercises\n  \n    .heading {\n      // exercise heading/numbers regular size\n      font-size: inherit;\n    } \n  }\n}\n\n// subtasks are indented\n.exercise-like > .exercise-like.task {\n  margin-left: 20px;\n}\n\n\n\n// ---------------------------------------------------------\n// exercise-wrapper is used for WW problems\n// these rules need testing/refactoring\n\n.exercise-wrapper form button:hover {\n  cursor: pointer;\n  background-color: #e0e0ff;\n  border: 1px solid #000;\n}\n.exercise-wrapper form button:active {\n  background-color: #f0f0f0;\n}\n.exercise-wrapper form button + button {\n  margin-left: 0.8em;\n}\n\n.exercise-wrapper,\n.exercise-wrapper form,\n.exercise-wrapper form > div:first-child {\n  display: inline-block;\n  vertical-align: top;\n  width: 100%; /* for live ww to open at 100% wide */\n}\n\n.knowl .exercise-wrapper,\n.knowl .exercise-wrapper form,\n.knowl .exercise-wrapper form > div:first-child {\n  width: 100%;\n}\n\n.exercise-wrapper > .para:first-child,\n.exercisegroup .exercise-wrapper > .para:first-child {\n  margin-top: 0;\n  display: inline;\n}\n\n/* next is related to having exercises start in-line with their exercise number,\n including when a static WW problem is made interactive */\n/* not sure this was the right way to do it */\n/* see https://opentext.uleth.ca/apex-calculus/sec_antider.html#exercise-722 */\n.heading + .exercise-wrapper {\n  display: inline-block;\n  max-width: 95%;\n  width: 100%;\n}\n\n.cols2 .heading + .exercise-wrapper {\n  width: auto;\n}\n", "// \n\n/* stacked headings in the solutions backmatter */\nsection.solutions > .heading + .heading {\n  margin-top: 0.5em;\n}\n\nsection.solutions > h3.heading,\nsection.solutions section > h3.heading {\n  font-size: 1.6em;\n}\n\nsection.solutions > h4.heading,\nsection.solutions section > h4.heading {\n  font-size: 1.45em;\n}\n\nsection.solutions > h5.heading,\nsection.solutions section > h5.heading {\n  font-size: 1.35em;\n}\n\nsection.solutions > h6.heading,\nsection.solutions section > h6.heading {\n  font-size: 1.25em;\n}\n", "// Space all rows in a sbsgroup, no other styling\n.sbsgroup > *:not(:first-child)\n{\n    margin-top: 1.5em;\n}\n\n\n// sidebysides get laid out into a grid with two rows. \"Plain panels\" without\n// a caption are in the first row. Panels with things like tables/figures with\n// captions we want to align are decomposed across two rows.\n// If there is no content (no captions) in a second row, it will collapse.\n\n// 1| plain panel | figure-like/table-like\n// 2|             | figcaption\n.sbsrow {\n  display: grid;\n  grid-template-rows: auto auto;\n}\n\n.sbspanel {\n  // most sbspanels are in the first row\n  grid-row: 1; \n\n  // tables and their captions get centered when in panels\n  & > .table > figcaption {\n    text-align: center;\n  }\n  .tabular {\n    overflow-x: auto;\n    margin-left: auto;\n    margin-right: auto;\n  }\n}\n\n\n// panel content alignment options\n.sbspanel--top {\n  align-self: start;\n}\n\n.sbspanel--middle {\n  align-self: center;\n}\n\n.sbspanel--bottom {\n  align-self: end;\n}\n\n\n// sbspanels with figures or tables get decomposed into two rows\n// both the panel and the figure-like/table-like element should\n// be ignored by the grid layout so we can place the items inside\n// the *-like into the grid\n.sbspanel:has(.figure-like, .table-like),\n.sbspanel > :is(.figure-like, .table-like) {\n  display: contents;\n}\n\n\n// first child of decomposed *-like goes to the first row\n.sbspanel > :is(.figure-like, .table-like) > *:first-child {\n  grid-row: 1;\n  align-items: start;\n  align-self: start;\n}\n\n// and gets alignment info\n.sbspanel--top > :is(.figure-like, .table-like) > *:first-child {\n  align-items: start;\n  align-self: start;\n}\n\n.sbspanel--middle > :is(.figure-like, .table-like) > *:first-child {\n  align-items: center;\n  align-self: center;\n}\n\n.sbspanel--bottom > :is(.figure-like, .table-like) > *:first-child {\n  align-items: end;\n  align-self: end;\n}\n\n\n// second child of decomposed *-like goes to the second row\n.sbspanel > :is(.figure-like, .table-like) > *:nth-child(2) {\n  margin-top: 0.5em;\n  grid-row: 2;\n  width: 100%;\n}\n\n\n// make sure content for a panel stays in the correct column\n// otherwise captions may shift left into columns that do not have\n// second row content\n@for $col from 2 through 10 {\n  .sbspanel:nth-of-type(#{$col}) * {\n    grid-column: #{$col};\n  }\n}", "// Generate styles for an inline heading\n@mixin heading {\n  & > .heading:first-child {\n    display: inline;\n    line-height: initial;\n    border-bottom: 0;  // disable underline that may come from underlined headings\n\n    &:after {\n      content: \"\\2009\";\n    }\n\n    // Following sibling also needs to be inline for heading to line up correctly\n    // For now limit to logical paragraphs and introductions as they seem to cover\n    // the plain text cases. Not clear we would want same treatment for other\n    // kinds of content\n    & + :is(.para, .para.logical, .introduction) {\n      display: inline;\n      // possible first child that is the actual text\n      & > .para:first-child {\n        display: inline;\n        }\n      // an introduction could have a para.logical with a para\n      & > .para.logical:first-child > .para:first-child {\n        display: inline;\n      }\n    }\n  }\n}\n", "@use './helpers/inline-heading-mixin';\n\n.discussion-like {\n  @include inline-heading-mixin.heading;\n  & > .heading {\n    ::after {\n      content: \"\\2009\";\n    }\n\n    & + .para {\n      display: inline;\n    }\n\n    .space,\n    .codenumber,\n    .period {\n      display: none;\n    }\n\n    .type::after {\n      content: \". \";\n    }\n  }\n}\n", "/*\n  main knowls styles\n*/\n\n$border-radius: 0px !default;\n$border-width: 3px !default;\n$pad: 12px !default;\n\n.source-view__link,\n.knowl__link {\n  cursor: pointer;\n  margin-left: 0.1em;\n  margin-right: 0.1em;\n  color: var(--knowl-link-color);\n  border-bottom: 1px dotted var(--knowl-link-color);\n}\n\n.source-view {\n  margin: 0.5em 0;\n}\n\nsummary.source-view__link,\nsummary.knowl__link {\n  display: list-item inline;\n}\n\n.source-view__link > *,\n.knowl__link > * {\n  display: inline;\n}\n\n.source-view__link:is(:hover, :focus, [open]),\n.knowl__link:is(:hover, :focus, [open]) {\n  background-color: var(--knowl-background);\n  border-bottom-color: transparent;\n}\n\n.source-view__content {\n  margin: 0.2em 0;\n}\n\n.knowl__content {\n  margin: 0.75em 0;  //at least this much space above/below\n  border: $border-width solid var(--knowl-border-color);\n  border-radius: $border-radius;\n  padding: $pad;\n  background-color: var(--knowl-background);\n\n  .incontext {\n    display: block;\n    font-size: 85%;\n    text-align: right;\n  }\n}\n\n/* nested knowl alt colors */\n.knowl__content .knowl__content {\n  background-color: var(--knowl-nested-1-background);\n}\n\n.knowl__content .knowl__content .knowl__content {\n  background-color: var(--knowl-nested-2-background);\n}\n\n.knowl__content .knowl__content .knowl__content .knowl__content {\n  background-color: var(--knowl-nested-3-background);\n}\n\n.knowl__content .knowl__content .knowl__content .knowl__content .knowl__content {\n  background-color: var(--knowl-nested-4-background);\n}\n\n\n/* spacing tweaks inside knowls */\n.knowl__content > figure {\n  margin-left: 0;\n  margin-right: 0;\n}\n", "// Standard collection of chunks. This file should only be modified\n// to fix bugs or improve the default-modern theme. If you want to\n// make changes for use in some other theme, create a _chunks-XXX file\n// in that theme's directory.\n\n$border-radius: 8px !default;\n\n// One stop include for default style content blocks\n@use 'components/chunks/asides-floating';\n@use 'components/chunks/codelike';\n@use 'components/chunks/exercises';\n@use 'components/chunks/solutions';\n@use 'components/chunks/sidebyside';\n@use 'components/chunks/discussion-inline';\n@use 'components/chunks/knowls' with ($border-radius: $border-radius);\n\n@use 'components/chunks/helpers/inline-heading-mixin';\n\n\n.theorem-like,\n.definition-like,\n.example-like,\n.project-like,\n.remark-like,\n.openproblem-like,\n.computation-like,\n.assemblage-like {\n  > .heading {\n    display: block;\n    font-size: 1.1em;\n  }\n}\n\n.proof {\n  padding-bottom: 1.5em;\n  &::after {\n    content: \"□\";\n    float: right;\n  }\n\n  .heading {\n    font-size: unset;\n    font-weight: bold;\n    font-style: italic;\n  }\n}\n\n.solution-like {\n  .heading {\n    display: inline;\n    font-style: italic;\n    font-size: unset;\n  }\n}\n\n\n .goal-like {\n  border: none;\n  padding: 0;\n}\n\n.goal-like > .heading {\n  margin-top: -0.5em;\n  padding: 0;\n  margin: 0;\n  font-size: 1.1em;\n}\n\n.paragraphs,\narticle {\n  @include inline-heading-mixin.heading;\n}\n", "// Basic spacing for content\n\n// Breakpoint at which the navbar moves to the bottom of the screen\n$navbar-breakpoint: 800px !default;\n\n// all styling assumes border-box layout measurement\n* {\n  box-sizing: border-box;\n}\n\n//----------------------------------------------------------\n// Inter item vertical spacing\n//\n// Set some baseline minimal inter-item vertical spacings\n//\n// Individual items can override this with their own margin. The\n// user of @layer here forces these rules to all have less precedence\n// than any rules not in a layer.\n// Most spacing should be done with margin-top.\n\n@layer spacing {\n  // inter-item spacing high level containers\n  :is(section, article, .knowl__content) > *:not(:first-child) {\n    margin-top: 1.5em;\n  }\n\n  // but tighten up spacing slightly for adjacent paragraphs in a section\n  :is(section, article, .knowl__content) > .para + .para {\n    margin-top: 1em;\n  }\n\n  // lower-level container elements that are expected to contain sequences of items\n  // tighter spacing here to avoid visually breaking up the minor container\n  .ptx-content :is(ul, td, li, dd, .blockquote, .sbspanel, .para.logical) > *:not(:first-child) {\n    margin-top: 0.5em;\n  }\n}", "// Types of ol/ul - used by web and ebooks\n// Any spacing should be in _lists.scss, not here\n\nol.no-marker,\nul.no-marker,\nli.no-marker {\n    list-style-type: none;\n}\n\nol.decimal {\n    list-style-type: decimal;\n}\n\nol.lower-alpha {\n    list-style-type: lower-alpha;\n}\n\n// Match LaTeX style for second level (i.e. level=\"1\") lists\nol.lower-alpha-level-1 > li::marker {\n    content: \"(\"counter(list-item,lower-alpha)\") \";\n}\n\nol.upper-alpha {\n    list-style-type: upper-alpha;\n}\n\nol.lower-roman {\n    list-style-type: lower-roman;\n}\n\nol.upper-roman {\n    list-style-type: upper-roman;\n}\n\nul.disc {\n    list-style-type: disc;\n}\n\nul.square {\n    list-style-type: square;\n}\n\nul.circle {\n    list-style-type: circle;\n}\n", "/* dl is used for glossaries and descriptions lists.\n   Glossaries are simple:  bold word by itself on a line.\n        Definition indented on the next line.\n        Vertical space before the next term.\n\n   Description lists are more complicated.  The wider version\n   (refering to the horizontal indentation of the definition;\n    this is the default)\n   has the (wrapped) term inline with the definition.\n\n   The narrow version is complicated because the term is inline\n   with its definition if it fits, otherwise it is on the line above.\n   That means the vertical space between entries can't be handled by\n   a top margin on the dt.  Instead we have an ::after on the dd .\n */\n\ndl:is(.description-list, .glossary) {\n  margin: 0;\n  //overflow: hidden; // Removed to show permalinks\n\n  dt {\n    font-weight: bold;\n    max-width: 55ex;\n  }\n\n  dd::after {\n    content: \"\";\n    display: block;\n    clear: both;\n  }\n}\n\n.para > dl:is(.description-list) {\n  // add some space when inside a .para\n  margin-top: 0.5em;\n  margin-bottom: 0.5em;\n}\n\ndl.glossary {\n  dt {\n    margin-top: 1.25em;\n\n    &:first-of-type {\n      margin-top: 0;\n    }\n  }\n\n  dd {\n    margin-left: 5ex;\n  }\n}\n\ndl.description-list {\n\n  dt,\n  dd {\n    margin-top: 1em;\n\n    &:first-of-type {\n      margin-top: 0;\n    }\n  }\n\n  dt {\n    float: left;\n    clear: both;\n    text-align: right;\n    width: 18ex;\n    margin-right: 1ex;\n  }\n\n  dd {\n    margin-left: 22ex;\n  }\n\n  &.narrow {\n    dt {\n      width: 11ex;\n    }\n\n    dd {\n      margin-left: 15ex;\n    }\n  }\n\n  &.wide {\n    dt {\n      width: 25ex;\n    }\n\n    dd {\n      margin-left: 29ex;\n    }\n  }\n}\n\ndl.description-list dt:first-of-type {\n  clear: none;\n}\n\n.description-list + * {\n  clear: both;\n}\n\n/* where do we have nested dl? */\ndl.description-list dl dt {\n  width: 8ex;\n}\n\ndl.description-list dd dd {\n  margin-left: 18ex;\n}\n\ndl.description-list dl dd {\n  margin-left: 12ex;\n}\n\n\n@media screen and (max-width: 480px) {\n  dl.description-list dt {\n    float: none;\n    margin-left: 0;\n    text-align: left;\n  }\n\n  dl.description-list dd,\n  dl.description-list.narrow dd,\n  dl.description-list.wide dd {\n    margin-top: 0.5em;\n    margin-left: 3em;\n    max-width: calc(100% - 3em);\n  }\n}\n", "// Entry point for ol/ul/dl web styling\n\n@use \"list-styles\";\n@use \"description-lists\";\n@use '../helpers/cols';\n\n// generate multi column rules for lists\n@include cols.allow-cols('li');\n\n// use .ptx-content to avoid styling lists in toc/header/etc...\n.ptx-content {\n  ol,\n  ul {\n\n    ol,\n    ul {\n      // margin-top: 0.5em;\n    }\n  }\n\n  li {\n    margin-top: 0.5em;\n    // margin-bottom: 0;\n\n    // & > .para:first-child {\n    //     margin-top: 0;\n    // }\n\n    .li--heading-title {\n      font-size: 100%;\n      font-weight: normal;\n      font-style: italic;\n    }\n  }\n}   // .ptx-content\n\n.para > :is(ol, ul) {\n  // add some space when inside a .para\n  margin-top: 0.5em;\n  margin-bottom: 0.5em;\n}\n\n// provide space for custom markers\nol > li {\n  padding-left: 0.25em;\n}\n", "\n.fillin {\n  display: inline-block;\n  border: none;\n  border-width: 1px;\n  margin-right: 0.1em;\n  margin-left: 0.1em;\n  margin-bottom: -0.25em;\n\n  &.underline {\n    border-bottom-style: solid;\n    border-width: 1px;\n  }\n\n  &.box {\n    outline: 1px solid var(--body-text-color);\n    height: 1.3em;\n  }\n\n  &.shade {\n    background-color: var(--fillin-background-color, #eee);\n    height: 1.3em;\n  }\n}\n\n\n:root.dark-mode {\n  --fillin-background-color: #444;\n}\n", "// headings for standard page elements - sections/articles/etc...\n// more specialized headings (exercises) should be defined in the specific component\n// complex stylizing (like boxes) should be done by \"chunks\"\n\n// reset size/margin for headings\n.heading:is(h1, h2, h3, h4, h5, h6) {\n  margin: 0;\n  font-size: unset;\n}\n\n.heading {\n  line-height: 1.1;\n  font-family: var(--font-headings);\n  font-weight: 700;\n  margin-top: 0;\n  margin-bottom: 0;\n}\n\nsection > .heading {\n  font-size: 1.75em;\n  color: var(--body-title-color);\n  line-height: 1.25em;\n  margin-top: 2.5em;\n  margin-bottom: 0.5em;\n\n  // pull in any following items that default to a larger top margin\n  & + * {\n    margin-top: 0.5em;\n  }\n}\n\n.ptx-content > section > .heading {\n  //first heading on page\n  margin-top: 0.5em;\n}\n\nsection section > .heading {\n  font-size: 1.5em;\n  margin-top: 2em;\n}\n\nsection section section > .heading {\n  font-size: 1.40em;\n  margin-top: 2em;\n}\n\n\narticle > .heading {\n  font-size: 1.25em;\n  margin-top: 1.5em;\n\n  // pull in any following items that default to a larger top margin\n  & + * {\n    margin-top: 0.5em;\n  }\n}\n\n.paragraphs > .heading {\n  font-size: 1.125em;\n}\n\n// heading followed by no content and then a subsection that starts with heading\n:is(section, article) > .heading + :is(section, article) > .heading {\n  margin-top: 0.5em;\n}\n\n// smaller headings on phone screens\n@media screen and (max-width: 480px) {\n  section > .heading {\n      font-size: 1.5em;\n      line-height: 1.33em;\n      margin-top: 1em;\n  }\n  section section > .heading {\n      font-size: 1.3em;\n      line-height: 1.15em;\n  }\n  section section section > .heading {\n      font-size: 1.15em;\n      line-height: 1em;\n  }\n}\n\n.heading.hide-type > .type {\n  display: none;\n}\n", "\n// Reset for all links\na {\n  color: var(--link-text-color);\n  text-decoration: none;\n\n  &:hover,\n  &:focus {\n    text-decoration: none;\n  }\n}\n\n\na[href^=\"mailto:\"] {\n  white-space: pre;\n}\n\n\n// Body links. .ptx-content to avoid hitting navbar, toc, etc...\n.ptx-content {\n  a.internal {\n    color: var(--link-text-color);\n    font-weight: bold;\n  }\n  a.external {\n    color: var(--link-alt-text-color);\n    font-weight: bold;\n  }\n  a.internal:hover, a.internal:hover *,\n  a.internal:focus, a.internal:focus * {\n    color: var(--link-active-text-color);\n    background-color: var(--link-active-background);\n    font-weight: bold;\n  }\n  a.external:hover, a.external:hover *,\n  a.external:focus, a.external:focus * {\n    color: var(--link-alt-active-text-color);\n    background-color: var(--link-alt-active-background);\n    font-weight: bold;\n  }\n}\n", "// limit rules targeting basic elements to just content area\n.ptx-content {\n  table {\n    border-spacing: 0;\n    border-collapse: collapse;\n  }\n\n  td {\n    padding: 2px 5px;\n    font-size: 90%;\n\n    img {\n      max-width: 200px;\n      margin-right: 30px;\n    }\n  }\n\n  th {\n    padding: 2px 5px;\n  }\n\n  // generate alignment/border mixin classes for both th and td\n  @each $cell-type in (th, td) {\n    #{$cell-type} {\n      .lines {\n        white-space: nowrap;\n      }\n\n      // horizontal alignment options\n      @each $class, $align in (l: left, c: center, r: right, j: justify) {\n        &.#{$class} {\n          text-align: $align;\n        }\n      }\n\n      // vertical alignment options\n      @each $class, $align in (t: top, b: bottom, m: middle) {\n        &.#{$class} {\n          vertical-align: $align;\n        }\n      }\n\n      // border options\n      @each $side, $side-symbol in (left: l, right: r, top: t, bottom: b) {\n        @for $i from 0 through 3 {\n          &.#{$side-symbol}#{$i} {\n            @if $i ==0 {\n              border-#{$side}: none;\n            }\n\n            @else {\n              border-#{$side}: #{$i}px solid var(--body-text-color);\n            }\n          }\n        }\n      }\n    }\n  }\n\n\n  // when cells do not have a border on left and right, add padding\n  th.r0.l0,\n  td.r0.l0  {\n    padding-left: 0.8em;\n    padding-right: 0.8em;\n  }\n\n  tr.header-vertical {\n    th {\n      writing-mode: vertical-rl;\n      padding-left: 2em;\n    }\n  }\n\n  .center {\n    table {\n      text-align: center;\n      margin-left: auto;\n      margin-right: auto;\n    }\n  }\n}\n\n// Rules with non-generic targeting\n\n.tabular-box {\n  margin-top: 0.5em;  //minimum space above to separate from figcaption\n  overflow-x: auto;\n}\n\n.tabular-box.natural-width table {\n  margin-left: auto;\n  margin-right: auto;\n}\n\n// More specific types of tables\n\ntable.notation-list {\n  tr {\n    th {\n      text-align: left;\n      margin-left: 1em;\n    }\n\n    td {\n      text-align: left;\n      vertical-align: top;\n    }\n  }\n}\n\n\n\n", "// Styles for the items that are (at least generally) a part of the front matter\n// There are some pretty generic class names. Those get wrapped with a class\n// limiting their scope to the expected page\n\n.frontmatter {\n  & > .heading {\n    display: block;\n    text-align: center;\n  }\n\n  & > .heading .title,\n  .book > .heading .title {\n    font-size: 1.3em;\n  }\n\n  & > .heading .subtitle,\n  .book > .heading .subtitle {\n    display: block;\n    font-weight: normal;\n    color: var(--byline-color);\n    font-size: 0.875em;\n    line-height: 1.42857em;\n    margin-top: 0.35714em;\n  }\n\n  & > .para:first-of-type {\n    margin-top: 4em;\n  }\n\n  & > .author,\n  & > .credit {\n    margin-top: 2em;\n    text-align: center;\n  }\n\n  .author:first-of-type {\n    margin-top: 4em;\n  }\n\n  & > .author .author-name {\n    font-size: 120%;\n  }\n\n  .date {\n    display: block;\n    margin-top: 2em;\n    text-align: center;\n  }\n\n  .credit .title {\n    font-size: 1em;\n  }\n\n  .credit .author {\n    font-size: 0.9em;\n    margin-top: 0.75em;\n  }\n\n  .author-info {\n    font-size: 90%;\n  }\n\n  .summary-links {\n    margin-top: 4em;\n  }\n\n  .abstract {\n    margin: 4em 2em;\n  }\n\n  .keywords, .support {\n    margin-top: 2em;\n  }\n\n  .abstract, .keywords, .support {\n    & > .title {\n      font-size: 1.125em;\n      font-weight: 600;\n      line-height: 1.125em;\n      display: inline;\n    }\n\n    & > .title::after {\n      content: \".\\2009\\2009\\2009\";\n    }\n\n    & > .title + .para {\n      display: inline;\n    }\n  }\n\n  .colophon {\n    .copyright {\n      margin-top: 2.5em;\n    }\n\n    .license {\n      margin-top: 2.5em;\n    }\n  }\n}\n", "\n/* Start of division toc links */\n// .ptx-content to override _links rules\n.ptx-content .summary-links {\n  font-family: var(--font-headings);\n  display: block;\n  margin-top: 1em;\n\n  a {\n    color: var(--summary-link-text-color);\n    background: var(--summary-link-background);\n    font-size: 1.5em;\n    line-height: 1.25em;\n    padding: 10px 20px;\n    padding-right: 60px;\n    border-radius: 3px;\n    position: relative;\n    display: block;\n    font-weight: unset;\n\n    .title{\n      font-style: normal;\n    }\n\n    .codenumber {\n      margin-right: 0.41667em;\n    }\n\n    &::after {\n      // triangles\n      right: 0.83333em;\n      content: \"\";\n      position: absolute;\n      top: 50%;\n      margin-top: -0.4em;\n      width: 0;\n      height: 0;\n      border-top: 0.4em solid transparent;\n      border-bottom: 0.4em solid transparent;\n      border-left: 0.4em solid var(--summary-link-text-color);\n    }\n\n    &:hover {\n      color: var(--summary-link-hover-text-color);\n      background: var(--summary-link-hover-background);\n\n      // need to override work done in _links\n      * {\n        color: var(--summary-link-hover-text-color);\n        background: var(--summary-link-hover-background);\n      }\n      .title {\n        font-weight: normal;\n      }\n\n      &::after {\n        border-left: 0.4em solid var(--summary-link-hover-text-color);\n      } \n    } \n  }\n\n  ul {\n      list-style-type: none;\n      padding: 0;\n      margin-top: 0;\n  }\n\n  li {\n      margin-top: 5px;\n  }\n}\n\n@media screen and (width <= 480px) {\n  .ptx-content .summary-links a {\n    //shrink on mobile\n    font-size: 100%;\n    line-height: 1.25em;\n  }\n}\n", "$border-radius: 0px !default;\n\n.ptx-footnote {\n  display: inline-block;\n  position: relative;\n}\n\n.ptx-footnote[open] {\n  display: contents;\n}\n\n\n.ptx-footnote[open] .ptx-footnote__number::before {\n  font-size: smaller;\n  content: \"[x]\";\n  visibility: visible;\n  vertical-align: super;\n}\n\n.ptx-footnote[open] .ptx-footnote__number sup {\n  display: none;\n}\n\n.ptx-footnote__number {\n  display: inline-block;\n  cursor: pointer;\n  min-width: 1em; //hopefully enough space...\n}\n\n.ptx-footnote__number::marker {\n  content: \"\";\n}\n\n.ptx-footnote__contents {\n  display: block;\n  font-style: italic;\n  background: var(--knowl-background);\n  border-radius: $border-radius;\n  padding: 8px;\n  margin: 4px auto;\n  width: fit-content;\n  max-width: calc(100% - 60px);\n  border: 2px solid var(--knowl-border-color);\n  //reset color/weight/size in case used in block that changed them\n  // e.g. theorem title in denver\n  color: var(--body-text-color);\n  font-weight: normal;\n  font-size: var(1rem);\n}\n", "\n\n/* the index at the back of the book */\n// TODO - refactor\n\n\n.navbar .indexnav {\n  position: absolute;\n  top: 46px;\n  right: 0;\n}\n\n.mininav {\n  float: left;\n  padding-top: 0.7ex;\n  padding-left: 1ex;\n}\n\n\n.indexjump {\n  margin-left: 1.5ex;\n  margin-top: 0.2ex;\n  padding-top: 0;\n  float: left;\n  line-height: 0.95;\n}\n\n.indexjump a {\n  padding-left: 2.5px;\n  padding-right: 0.5px;\n  width: 2.5ex;\n/*\n*  *  omitted, because we put a space in the source\n*      padding-right: 3px;\n*      */\n  margin-right: -1px;\n  color: inherit;\n  font-size: 80%;\n  text-align: center;\n}\n.indexjump a::after{\n  content: \"\";\n  display: inline-block;\n}\n.indexjump a:nth-of-type(14){\n  padding-left: 1.8ex;\n}\n.indexjump a:last-child {\n  padding-right: 10px;\n}\n\n.indexjump a:hover {\n  background: var(--activated-content-bg);\n}\n\n.indexitem {\n  margin-top: 4px;\n}\n\n.subindexitem {\n  margin-left: 2em;\n  font-size: 95%;\n  margin-top: -1px;\n}\n\n.subsubindexitem {\n  margin-left: 3.5em;\n  font-size: 95%;\n  margin-top: -1px;\n}\n\n.indexknowl {\n  margin-left: 0.11em;\n}\nem + .indexknowl  {\n  margin-left: -0.25em;\n}\n.indexknowl a {\n  margin-left: 2em;\n}\n\n.indexitem .see,\n.subindexitem .see,\n.subsubindexitem .see {\n  margin-left: 1em;\n  margin-right: 0;\n}\n.indexitem .seealso,\n.subindexitem .seealso,\n.subsubindexitem .seealso {\n  margin-left: 1em;\n  margin-right: 0;\n}\n.indexitem .see em,\n.subindexitem .see em,\n.subsubindexitem .see em,\n.indexitem .seealso em,\n.subindexitem .seealso em,\n.subsubindexitem .seealso em {\n  margin-right: 0.25em;\n  font-style: italic;\n}\n/*  note that multiple things after \"see\" are in separate spans */\n.indexitem .see + .see,\n.subindexitem .see + .see,\n.subsubindexitem .see + .see,\n.indexitem .seealso + .seealso,\n.subindexitem .seealso + .seealso,\n.subsubindexitem .seealso + .seealso {\n   margin-left: 0;\n   margin-right: 0;\n}\n\n.indexitem .indexknowl {\n  font-size: 90%;\n}\n\n.indexitem [data-knowl], .subindexitem [data-knowl], .indexitem [data-knowl]:hover {\n  padding-right: 2px;\n  padding-left: 2px;\n}\n.indexknowl [data-knowl]:hover, .indexknowl .active[data-knowl] {\n  margin-left: 2em;\n}\n\n.subindexitem .indexknowl {\n  font-size: 95%;\n}\n.subsubindexitem .indexknowl {\n  font-size: 95%;\n}\n\n.indexletter {\n  margin-top: 1.5em;\n}\n", "// ---------------------------------------------\n// containers for images, audio, video, and asymptote\n.image-box,\n.audio-box,\n.video-box,\n.asymptote-box {\n    position: relative;\n}\n\n.image-box .asymptote-box iframe.asymptote,\niframe.asymptote,\n.video-box .video,\n.video-box .video-poster {\n    position: absolute; top: 0; left: 0; width: 100%; height: 100%;\n}\n\n// images in containers should grow to fit space\n.image-box img,\nimg.contained {\n    width: 100%;\n}\n\n// ---------------------------------------------\n// images\n.ptx-content img, .ptx-content svg {\n  // for body images in dark mode, we want to be able to force a light colored background\n  // as most transparent images will assume that the background is white\n  background: var(--ptx-image-bg);\n}\n// but mermaid svg should always have a transparent background\n.mermaid > svg {\n  background: none;\n}\n\n.image-description {\n  summary {\n    list-style: none; // no marker\n    cursor: pointer;\n  }\n}\n\n// download links after an image\n.image-archive {\n  margin: 0.75em auto 0;\n  font-family: var(--font-monospace);\n  justify-content: center;\n  display: flex;\n  gap: 0.5em;\n}\n\n// TODO - refactor mag_popup JS and CSS\n// was .ptx-content .image-box > img:not(.draw_on_me):not(.mag_popup)\n.image-box > img:not(.mag_popup) {\n  cursor: zoom-in;\n}\n\nimg.mag_popup {\n  border: 1px solid #666;\n  box-shadow: 4px 6px 4px #999;\n  cursor: zoom-out;\n}\n\n.mag_popup_container {\n  width:100%;\n  position:absolute;\n  z-index:1001;\n  overflow-x: visible;\n}\n\n// ---------------------------------------------\n// other\n.audio {\n    width: 100%;\n}\n\n.video-poster {\n    cursor: pointer;\n}\n", "figure {\n  clear: both;\n  position: relative;\n\n  // override browser margins\n  margin-left: 0;\n  margin-right: 0;\n}\n\nfigcaption {\n  margin-left: auto;\n  margin-right: auto;\n  margin-top: 0.5em;\n\n  code.code-inline {\n    white-space: pre;\n  }\n  \n  .codenumber,\n  .type {\n    font-weight: 700;\n  }\n\n  // add n-dashes\n  .codenumber::after,\n  .type:last-of-type::after {\n    content: \"\\2002\";\n  }\n\n  // make sure first para comes right after title\n  .para:first-of-type {\n    display: inline;\n  }\n}\n\n// tables are inset\nfigure.table-like {\n  margin-left: 30px;\n  margin-right: 30px;\n\n  // but lists can go full right\n  .list {\n    margin-right: 0;\n  }\n}\n\n@media (max-width <= 943px){\n  .figure-like {\n    overflow-x: auto;\n  }\n}\n", "/* style for poems */\n.poem {\n  display: table;\n  margin: 0 auto;\n  width: auto;\n  max-width: 90%;\n}\n\n.poem > .heading {\n  display: block;\n  text-align: center;\n}\n\nsection article.poem > .heading::after {\n  content: \"\";\n}\n\n.poem > .heading > .title {\n  font-weight: bold;\n  font-size: 1.2em;\n  line-height: 1.2em;\n}\n\n.poem .author {\n  font-style: italic;\n  margin-top: 0.75em;\n}\n\n.poem .author.left {\n  text-align: left;\n}\n\n.poem .author.center {\n  text-align: center;\n}\n\n.poem .author.right {\n  text-align: right;\n}\n\n.poem .stanza > .heading {\n  text-align: center;\n  font-weight: bold;\n  font-size: 1em;\n  line-height: 1em;\n}\n\n.poem .stanza + .stanza {\n  margin-top: 1em;\n}\n\n.poem .heading + .stanza {\n  margin-top: 0.2em;\n}\n\n.poem .heading + .line {\n  margin-top: 0.2em;\n}\n\n.poem .line.left {\n  text-align: left;\n  margin-left: 4em;\n  text-indent: -4em;\n}\n\n.poem .line.center {\n  text-align: center;\n}\n\n.poem .line.right {\n  text-align: right;\n}\n\n.poem .tab {\n  margin-left: 2em;\n}\n", "@use '../chunks/codelike';\n\n// Prism stylesheets built locally as default ones don't support light/dark switching\n// this is a merged version of the default and dark themes\n\n// Default prism styling\n// Blocks\npre[class*=\"language-\"] {\n  margin: 0;\n  overflow: auto;\n  border: 1px solid #e1e1e1;\n}\n\n// Inline code\n:not(pre) > code[class*=\"language-\"] {\n  padding: .1em;\n  border-radius: .3em;\n  white-space: normal;\n}\n\ncode[class*=\"language-\"],\npre[class*=\"language-\"] {\n  color: black;\n  background: #fdfdfd;\n  text-shadow: none;\n  font-family: var(--font-monospace);\n  text-align: left;\n  white-space: pre;\n  word-spacing: normal;\n  word-break: normal;\n  word-wrap: normal;\n  line-height: 1.2;\n  tab-size: 4;\n  hyphens: none;\n\n  &.code-inline {\n    // unclobber some inline code styles\n    @include codelike.code-inline-spacing();\n  }\n\n  &::selection,\n  & ::selection {\n    background: #b3d4fc;\n  }\n\n  .token {\n    \n    &:is(.comment,\n    .prolog,\n    .doctype,\n    .cdata) {\n      color: #2a9716;\n    }\n    \n    &.punctuation {\n      color: #000;\n    }\n    \n    &.namespace {\n      opacity: .9;\n    }\n    \n    &:is(.property,\n    .tag,\n    .boolean,\n    .number,\n    .constant,\n    .symbol,\n    .deleted) {\n      color: rgb(41, 120, 15);\n    }\n    \n    &:is(.selector,\n    .attr-name,\n    .string,\n    .char,\n    .builtin,\n    .regex,\n    .inserted) {\n      color: #a11;\n    }\n    \n    &:is(.operator,\n    .entity,\n    .url) {\n      color: #000;\n      background: none;\n    }\n    \n    &:is(.atrule,\n    .attr-value,\n    .keyword) {\n      color: #0679B7;\n    }\n    \n    &.function,\n    &.class-name {\n      color: #30a;\n    }\n    \n    &.important,\n    &.variable {\n      color: rgb(0, 0, 0);\n    }\n    \n    \n    &.important,\n    &.bold {\n      font-weight: bold;\n    }\n    \n    &.italic {\n      font-style: italic;\n    }\n    \n    &.entity {\n      cursor: help;\n    }\n  }\n  \n  // -------------------------------------------\n  // Line numbers\n  &.line-numbers {\n    position: relative;\n    padding-left: 3.8em;\n    counter-reset: linenumber;\n    overflow: auto;\n    \n    > code {\n      position: relative;\n      white-space: inherit\n    }\n    \n    .line-numbers-rows {\n      position: absolute;\n      pointer-events: none;\n      top: 0;\n      font-size: 100%;\n      left: -3.8em;\n      width: 3em;\n      letter-spacing: -1px;\n      border-right: 1px solid #999;\n      user-select: none\n    }\n    \n    .line-numbers-rows > span {\n      display: block;\n      counter-increment: linenumber\n    }\n    \n    .line-numbers-rows > span::before {\n      content: counter(linenumber);\n      color: #999;\n      display: block;\n      padding-right: .8em;\n      text-align: right\n    }\n  }\n  \n  \n  // -------------------------------------------\n  // Line highlighting\n  .line-highlight {\n    position: absolute;\n    margin-top: 4px;    // tune to match padding of containing pre\n    left: 0;\n    right: 0;\n    padding: inherit 0;\n    font-size: inherit;\n    background: hsla(24, 20%, 50%, 8%);\n    pointer-events: none;\n    line-height: inherit;\n    white-space: pre\n  }\n}\n\n// -------------------------------------------\n// Dark mode\n:root.dark-mode {\n  \n  /* Code blocks */\n  pre[class*=\"language-\"] {\n    border: 1px solid #3d3d3d;\n  }\n  \n  \n  // Darker styling to match Runesone's code mirror theme\n  code[class*=\"language-\"],\n  pre[class*=\"language-\"] {\n    color: white;\n    background: hsl(0, 0%, 8%);\n    \n    &::selection,\n    & ::selection {\n      background: hsl(200, 4%, 16%);\n    }\n    \n    /* Make the tokens sit above the line highlight so the colours don't look faded. */\n    .token {\n      position: relative;\n      z-index: 1;\n      \n      &:is(.comment,\n      .prolog,\n      .doctype,\n      .cdata) {\n        color: #68a950;\n      }\n      \n      &.punctuation {\n        color: white;\n        opacity: 1;\n      }\n      \n      &.namespace {\n        opacity: .9;\n      }\n      \n      &:is(.property,\n      .tag,\n      .boolean,\n      .number,\n      .constant,\n      .symbol,\n      .deleted) {\n        color: #abc792;\n      }\n      \n      &:is(.selector,\n      .attr-name,\n      .string,\n      .char,\n      .builtin,\n      .regex,\n      .inserted) {\n        color: #ca9147;\n      }\n      \n      &:is(.operator,\n      .entity,\n      .url) {\n        color: white;\n      }\n      \n      &:is(.atrule,\n      .attr-value,\n      .keyword) {\n        color: #2d94fb;\n      }\n      \n      &.function,\n      &.class-name {\n        color: #e3e1c2;\n      }\n      \n      &.important,\n      &.bold {\n        font-weight: bold;\n      }\n      \n      &.italic {\n        font-style: italic;\n      }\n      \n      &.entity {\n        cursor: help;\n      }\n      \n    }\n  }\n  \n  .line-highlight {\n    background: hsla(0, 0%, 33%, 10%);\n    border-bottom: 1px dashed hsl(0, 0%, 33%);\n    border-top: 1px dashed hsl(0, 0%, 33%);\n    z-index: 0;\n  }\n}\n\n@media print {\n  code[class*=\"language-\"],\n  pre[class*=\"language-\"] {\n    .line-highlight {\n      color-adjust: exact\n    }\n  }\n}\n", "// TODO - refactor\n\n.displaymath {\n  overflow-x: auto;\n  overflow-y: hidden;\n}\n\n.displaymath mjx-container[jax=\"CHTML\"][display=\"true\"] {\n  margin: 0 0 0 0;  // container is going to apply margin, so remove it from mjx-container\n  padding-top: 2px; // Chrome sometimes clips the top 1-2 pixels of math after it has been scaled - provide room for that content\n}\n\n.process-math mjx-container svg {\n  // remove the background that is normally applied to svg's by PreTeXt CSS\n  // we use .process-math instead of .displaymath to get inline math as well.\n  background: none;\n}\n\n// ?\n[data-knowl] > mjx-mrow .TEX-I {\n  font-family: MJXZERO !important;\n  font-style: normal !important;\n}\n\n/* remove this when MathJax fixes the bug that was setting the width to 0 */\n/* as in  $x=0$.  becomes  $x=0\\text{.}$ */\n.knowl mjx-mtext > mjx-utext,\nmjx-mtext > mjx-utext {\n    width: revert !important;\n}\nmjx-msup mjx-utext,\nmjx-msub mjx-utext {\n    display: inline;\n}\n", "// TODO - refactor\n$opacity: 0.0 !default;\n\n/*\nSo that we can position things (like .autopermalink) absolutely wrt these items.\nAny element whose permalink should be positioned directly to the left of it\nshould be in this list.\n*/\nsection,\narticle,\nli,\nblockquote,\nfigcaption,\ndt,\n.exercisegroup,\n.discussion-like,\n.solution-like,\n.para {\n  position: relative;\n}\n\n.autopermalink {\n  position: absolute;\n  display: inline-block;\n  top: 0.5ex;\n  left: -2em;\n  font-size: 85%;\n  // variable allows theme to set different opacities for dark/light\n  opacity: var(--permalink-opacity, $opacity);\n  transition: opacity 0.2s;\n  margin-top: 0 !important;\n}\n\nli > .autopermalink {\n  left: -3.5em;\n}\n\n.autopermalink > * {\n  padding-left: 0.2em;\n  padding-right: 0.2em;\n}\n\n\n// Move permalink for division titles etc a little bit lower\n.appendix > .autopermalink,\n.chapter > .autopermalink,\n.index > .autopermalink,\n.section > .autopermalink,\n.subsection > .autopermalink,\n.references > .autopermalink,\n.exercises > .autopermalink {\n  top: 1.5ex;\n}\n\n// In some styles, the autopermalink for paras land right on the border line.\n// This is an attempt to fix that.  TODO: find a more robust solution, maybe\n// using a variable for the left offset of paras inside blocks.\n.assemblage-like > .para > .autopermalink,\n.example-like > .para > .autopermalink,\n.example-like > .exercise-like > .autopermalink,\n.project-like > .para > .autopermalink,\n.project-like > .exercise-like > .autopermalink,\n.project-like > .exercise-like > .introduction > .para > .autopermalink,\n.project-like > .exercise-like > .conclusion > .para > .autopermalink,\n.remark-like > .para > .autopermalink {\n  left: -2.9em;\n}\n\n\n.axiom-like, .example-like, .exercise-like, .solution-like, .assemblage-like, .definition-like, .remark-like, .project-like, .openproblem-like, .computation-like, .theorem-like, .proof, .case, li, dd {\n  > .para:first-of-type > .autopermalink {\n    display:none;\n  }\n\n  > .introduction > .para:first-of-type > .autopermalink {\n    display:none;\n  }\n}\n\n\n// Hover effects\n\n.ptx-content:has(.autopermalink:hover) .autopermalink {\n  opacity: 0.2;\n}\n\n.ptx-content:has(.autopermalink:hover) .autopermalink:hover {\n  opacity: 1;\n}\n\n.autopermalink:has(a:focus-visible) {\n  opacity: 1;\n}\n\n.permalink-alert {\n  position: absolute;\n  top: -3em;\n  left: 5em;\n  padding: 1.5em 2em;\n  background: var(--content-background);\n  border: 3px solid var(--page-border-color);\n  z-index: 2001;\n}\n\n\n/* when jumping to a permalink, push down so sticky navbar does not cover */\n:target {\n  scroll-margin-top: 45px;\n  // the \"pink flash\" when navigating to a target\n  animation: target-fade 10s 1;\n}\n\n@keyframes target-fade {\n    0% { background-color: var(--activated-content-bg) }\n    100% {\n      background-color: inherit;\n      opacity: 1;\n    }\n}\n", "\n// Miscellaneous stylized content blocks that are not complex enough\n// to warrant their own file\n\nem.alert {\n  font-weight: bold;\n}\n\n.bib {\n  margin-top: 0.25em;\n\n  .bibitem {\n    display: inline-block;\n    vertical-align: top;\n    width: 7%;\n    margin-right: 0;\n  }\n  \n  .bibitem + .bibentry {\n    display: inline-block;\n    width: 90%;\n    margin-top: 0;\n  }\n}\n\n\n\n.caption {\n  margin-top: 10px;\n  margin-left: auto;\n  margin-right: auto;\n  font-size: 100%;\n  text-align: center;\n}\n\n\n.contributor {\n  margin-top: 1.5ex;\n\n  &:first-child {\n    margin-top: 0em;\n  }\n\n  & + .para {\n    margin-top: 3ex;\n  }\n\n  .contributor-name {\n    font-variant: small-caps;\n  }\n\n  .contributor-info {\n    font-size: 88%;\n    font-style: italic;\n    margin-left: 3ex;\n  }\n}\n\n\n// Icon font settings\n.material-symbols-outlined {\n  font-variation-settings:\n  'FILL' 0,\n  'wght' 400,\n  'GRAD' 0,\n  'opsz' 24\n}\n\n\niframe {\n  margin: 0;\n  border: none;\n}\n\n\n.kbdkey {\n  background: #f1f1f1;\n  color: #333;\n  border: 1px solid #dddddd;\n  border-radius: 3px;\n  padding: 1px 2px 0 2px;\n  vertical-align: 0.1em;\n  font-size: 110%;\n  line-height: 1;\n  box-shadow: 2px 2px grey;\n  display: inline-block;\n  margin-right: 3px;\n}\n\n\n.unit,\n.quantity {\n    white-space: nowrap;\n    word-spacing: -0.25ex;\n    margin-right: 0.125em;\n\n    sub, sup {\n      word-spacing: normal;\n    }\n}\n\n\n.terminology {\n  font-style: italic;\n  font-weight: bold;\n}\n\n\n\n.times-sign {\n  font-size: larger;\n  vertical-align: -0.15ex;\n}\n\n\n.emphasis {\n  font-style: italic;\n\n  .emphasis {\n      font-weight: bold;\n  }\n}\n\n.definition-like .emphasis {\n  font-weight: 700;\n}\narticle.theorem-like .emphasis {\n  font-weight: 700;\n}\n\n.para {\n  line-height: 1.35;\n}\n\n.hidden {\n  display: none !important;\n}\n\n/* genus and species in italics */\n.taxon {\n  font-style: italic;\n}\n\n.quote {\n    padding-left: 40px;\n    padding-right: 10px;\n    margin-bottom: 1em;\n}\n\n.booktitle {\n    font-style: oblique;\n}\n\n/* Adapted from William Hammond (attributed to David Carlisle) */\n/* \"mathjax-users\" Google Group, 2015-12-27 */\n\n.latex-logo {font-family: \"PT Serif\", \"Times New Roman\", Times, serif;}\n\n.latex-logo .A {font-size: 75%; text-transform: uppercase; vertical-align: .5ex;\n         margin-left: -.48em; margin-right: -.2em;}\n\n.latex-logo .E {vertical-align:-.5ex; text-transform: uppercase;\n         margin-left: -.18em; margin-right: -.12em; }\n", "// Basic rules for printing a standard PreTeXt page\n\n// Get rid of UI elements.\n// Leave margin fiddling for system print dialog.\n\n// Worksheet and handout printing is handled in print-worksheet.scss\n\n@media print {\n  .pretext .ptx-masthead,\n  .pretext .ptx-navbar,\n  body.pretext > a.assistive,\n  .pretext .ptx-page > .ptx-sidebar,\n  .pretext  .ptx-page-footer,\n  .pretext .ptx-main > div.ptx-content-footer {\n    display:none;\n  }\n\n  .ptx-page, .ptx-main, .ptx-main .ptx-content {\n    all: unset !important;\n    width: 100%;\n    border: none;\n    padding: 0;\n    margin: 0;\n  }\n\n  .ptx-sagecell, .tabular, .table-like, .figure-like, .exercise-like {\n    break-inside: avoid;\n  }\n\n  .heading {\n    break-after: avoid;\n  }\n\n  .code-inline {\n    border: unset;\n    background: unset;\n  }\n\n  @page {\n    margin: 0.75in 0.75in 0.75in 0.75in;\n  }\n}\n", "// TODO refactor\n\n// Rules in this file apply to both screen and print\n// Print specific rules should go in a file in targets/print-worksheet stylesheet\n@use 'components/helpers/buttons-default' as buttons;\n\n.heading .print-links {\n  float: right;\n  vertical-align: bottom;\n  .print-link {\n    font-family: var(--font-body);\n    padding: 0.1em 0.2em;\n  }\n  .material-symbols-outlined {\n    margin-top:5pt;\n  }\n}\n\n", "// TODO - refactor\n// Make conditional on use of google search???\n\n.pretext .searchwrapper {\n  max-width: 900px;\n  position: absolute;\n  right: 0;\n  bottom: 0;\n  margin-bottom: 39px;\n}\n\n.pretext .searchwrapper .cse .gsc-control-cse,\n.pretext .searchwrapper .cse .gsc-control-cse input,\n.searchwrapper .gsc-control-cse {\n  padding: 5px;\n}\n\n// .pretext .searchwrapper .cse .gsc-search-button input.gsc-search-button-v2,\n// .searchwrapper input.gsc-search-button-v2 {\n//   padding: 2px 2px;\n// }\n\n// .pretext .searchwrapper form.gsc-search-box {\n//   margin: 0;\n// }\n\n// .pretext .searchwrapper table.gsc-search-box {\n//   margin: 0;\n// }\n\n// .pretext .searchwrapper .gsc-search-box-tools .gsc-search-box .gsc-input {\n//   padding: 0;\n// }\n\n// .pretext .searchwrapper .gsib_a {\n//   padding: 0 0 0 5px;\n// }\n\n// .pretext .searchwrapper .gsc-input-box {\n//   height: 3.0ex;\n// }\n\n// .pretext .searchwrapper form.gsc-search-box {\n//   font-size: 12px;\n// }\n", "\n@use 'components/helpers/buttons-default' as buttons;\n\n.searchbox {\n\n  .searchwidget {\n    height: 100%;\n  }\n  \n  .searchresultsplaceholder {\n    position: fixed;\n    top: 5vh;\n    bottom: 5vh;\n    padding: 1em;\n    left: max(10vw, calc(100vw - 800px) / 2);\n    width: 80vw;\n    max-width: 800px;\n    border: 2px solid var(--body-text-color);\n    background: var(--knowl-background, #eaf0f6);\n    z-index: 5000;\n    display: flex;\n    flex-direction: column;\n  }\n\n  .searchresultsplaceholder article {\n    width: 60%;\n    margin-left: auto;\n    margin-right: auto;\n    font-family: sans-serif;\n  }\n\n  .search-results-controls {\n    display: flex;\n    justify-content: space-between;\n    align-items: stretch;\n    gap: 10px;\n    margin-bottom: 1em;\n    height: 35px;\n  }\n\n  .ptxsearch {\n    flex: 1 1;\n  }\n  \n\n  .closesearchresults {\n    @include buttons.ptx-button;\n  }\n\n  .detailed_result {\n    margin-bottom: 10px;\n  }\n\n  .searchresults a:hover {\n    text-decoration: underline;\n    background: var(--link-active-background);\n  }\n\n\n  .searchresults {\n    padding-left: 10px;\n    margin-top: 0;\n    overflow-y: auto;\n    flex: 1 1;\n    background: var(--content-background, white);\n    border: 1px solid var(--page-border-color, #ccc);\n  }\n\n  .searchresults:empty {\n    display: none;\n  }\n  \n  .search-result-bullet {\n    list-style-type: none;\n  }\n\n  .search-result-score {\n    display: none;\n  }\n\n  //result qualities\n  .no_result {\n    font-size: 90%;\n    font-weight: 200;\n  }\n\n  .low_result {\n    font-weight: 200;\n  }\n\n  .medium_result {\n    font-weight: 500;\n  }\n  .high_result {\n    font-weight: 700;\n  }\n\n  .searchempty {\n    display: none;\n    padding-left: 10px;\n    padding-top: 5px;\n  }\n\n  .search-results-unshown-count {\n    margin-top: 0.6em;\n  }\n\n  .search-result-clip-highlight {\n    background: var(--searchresultshighlight);\n  }\n\n  .searchresultsbackground {\n    position: fixed;\n    top: 0;\n    background: var(--searchresultsbackground, white);\n    width: 100vw;\n    height: 100%;\n    left: 0;\n    z-index: 4999;\n  }\n\n  @media screen and (max-width: 800px) {\n    .searchresultsplaceholder {\n      bottom: 10vh;\n    }\n  }\n}\n\n:root {\n  --searchresultsbackground: #fff8;\n  --searchresultshighlight: rgba(255, 255, 0, 50%);\n}\n\n:root.dark-mode {\n  --searchresultsbackground: #0008;\n  --searchresultshighlight: rgba(255, 255, 0, 15%);\n}\n", "$border-radius: 0 !default;\n\n@mixin ptx-button(\n  $border-radius: $border-radius\n) {\n  font: inherit;\n  display: flex;\n  justify-content: center;\n  align-items: center;\n  padding: 0 10px;\n  gap: 10px;\n  min-height: 34px;\n  color: var(--button-text-color);\n  background-color: var(--button-background);\n  border-width: 1px;\n  border-color: var(--button-border-color);\n  border-style: solid;\n  border-radius: $border-radius;\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  cursor: pointer;\n\n  // Disable accidental text-selection\n  user-select: none;\n\n  &:hover:not(.disabled) {\n    color: var(--button-hover-text-color);\n    background-color: var(--button-hover-background);\n  }\n\n  &:focus-visible {\n    outline: 2px solid var(--button-text-color);\n    outline-offset: -2px;\n  }\n\n  &.disabled {\n    opacity: .4;\n    cursor: not-allowed;\n  }\n\n  &.hidden {\n    display: none;\n  }\n\n  &.open {\n    color: var(--button-hover-text-color);\n    background-color: var(--button-hover-background);\n  }\n}\n\n@mixin ptx-dropdown-button {\n  position: relative;\n\n  .dropdown-content {\n    display: none;\n    position: absolute;\n    background-color: var(--dropdown-background);\n    min-width: 160px;\n    z-index: 100;\n    border: 1px solid var(--dropdown-border-color);\n    right: 0;\n    top: 35px;\n    text-align: start;\n    padding: 0;\n\n    a {\n      display: block;\n      text-decoration: none;\n      color: var(--dropdown-text-color);\n      padding: 2px 8px;\n\n      &:is(:hover, :focus-visible) {\n        background-color: var(--dropdown-hover-background);\n        color: var(--dropdown-hover-text-color);\n      }\n    }\n\n    hr {\n      color: var(--dropdown-border-color);\n      margin: 4px 0;\n    }\n  }\n\n  &:is(:hover, :focus-visible, :focus-within) {\n    overflow: visible;\n\n    .dropdown-content {\n      display: block;\n    }\n  }\n}\n", "// extra specific to override Runestone margin\n.ptx-content .ptx-runestone-container .runestone {\n  margin: unset;\n  border-radius: 0;\n  border-width: 1px;\n}\n\n// avoid label splitting into multiple lines\n.multiplechoice_section label > .para {\n  display: inline;\n}\n\n// extra specific to override Runestone margin\n.ptx-content .ptx-runestone-container .ac_question { \n  max-width: var(--base-content-width);\n  margin: 0 auto 10px;\n}\n\n.runestone .runestone_caption {\n  // caption is always just something like \"ActiveCode\" in PTX\n  display: none;\n}\n\n\n/* to undo Runestone's draganddrop.css */\n.ptx-content .ptx-runestone-container .rsdraggable {\n  font-size: 100%;\n}\n\n// Unsure if still needed\n/* hack for runestone */\n/* to undo Runestone's presentermode.css */\n.ptx-content .bottom {\n    position: unset;\n}\n\n// override Runestone's pre formatting with these extra specific rules\n.ptx-runestone-container .runestone code,\n.ptx-runestone-container .runestone pre {\n  font-size: .93rem;\n  line-height: 1.2;\n  font-family: var(--font-monospace);\n}\n\n// override Runestone's pre formatting with these extra specific rules\n.ptx-runestone-container code[class*=\"language-\"],\n.ptx-runestone-container pre[class*=\"language-\"] {\n  color: black;\n  background: #fdfdfd;\n}\n\n//Fixup datafile captions\n.runestone.datafile {\n  .datafile_caption {\n    background: var(--code-inline-background);\n    border: 1px solid color-mix(in oklab, var(--code-inline-background) 50%, #888);\n    display: block;\n    width: fit-content;\n    margin: 0 auto;\n  }\n  img {\n    margin: 0 auto;\n    display: block;\n    border: 1px solid color-mix(in oklab, var(--code-inline-background) 50%, #888);\n  }\n  pre, textarea {\n    margin: 0 auto;\n    border: 1px solid color-mix(in oklab, var(--code-inline-background) 50%, #888);\n    background-color: var(--page-color);\n  }\n}\n.runestone.datafile + .program {\n  margin-top: 0;\n}\n\n// RS does not care what kind of element is used\n// PTX chooses to use a ul, so we will fix margins for it here instead of RS\nul[data-component=\"timedAssessment\"] {\n  margin: 0;\n  padding: 0;\n}\n\n:root.dark-mode {\n  // Darker styling to match Runesone's code mirror theme\n  .ptx-runestone-container code[class*=\"language-\"],\n  .ptx-runestone-container pre[class*=\"language-\"] {\n    color: white;\n    background: hsl(0, 0%, 8%);\n  }\n}\n", "// TODO - needs refactoring and dark mode update\n\n@use 'components/helpers/buttons-default' as buttons;\n\n/*  WW problems */\n.ptx-content .wwprob table.attemptResults {\n  margin-left: 2em;\n  background: #efefef;\n  padding: 0.2em;\n}\n\n.ptx-content .wwprob table.attemptResults + .attemptResultsSummary {\n  margin-top: 1em;\n}\n\n.ptx-content .wwprob .problem-main-form {\n  margin-top: 1em;\n  background: #eeeeff;\n  padding: 0.5em;\n}\n\n.ptx-content .wwprob td.ResultsWithoutError {\n  background: #9f9;\n}\n\n.ptx-content .wwprob td.ResultsWithError {\n  background: #f99;\n}\n\n.ptx-content .wwprob tr th {\n  text-align: center;\n  padding: 0.2em 1em 0.2em 1em;\n}\n\n.ptx-content .wwprob tr td {\n  text-align: center;\n}\n\n.ptx-content .wwprob tr td:empty {\n  background: #fff;\n}\n\n.ptx-content .wwprob ol,\n.ptx-content .wwprob ul {\n  margin-top: 0.75em !important;\n}\n\n.ptx-content .wwprob .problem {\n  background: #fdfdfd;\n}\n\n.ptx-content .wwprob .problem a {\n  text-decoration: none;\n}\n\n.ptx-content .wwprob #footer {\n  font-size: 70%;\n  text-align: right;\n}\n\n/* interactive WeBWorK */\n\nlabel.webwork {\n  display: inline-flex;\n  flex-direction: column;\n}\n\nlabel.correct .status {\n  background-color: #a0f0a0;\n}\n\nlabel.partly-correct .status {\n  color: #ffcc66;\n}\n\nlabel.incorrect .status {\n  color: #b00;\n}\n\nlabel.incorrect .status::before {\n  content: \" \";\n}\n\nlabel.feedback {\n  word-wrap: break-word;\n}\n\nlabel.correct .feedback {\n  background-color: #00ffcc;\n}\n\nlabel.partly-correct .feedback {\n  color: #ffcc66;\n}\n\nlabel.incorrect .feedback {\n  color: #e07070;\n}\n\n.webwork img,\n.webwork + .knowl-output img {\n  max-width: 100%;\n}\n\n// Make the default margin for items inside the exercise-wrapper similar to\n// default for items in a section\n.exercise-wrapper > *:not(:first-child) {\n  margin-top: 1.5em;\n}\n\n.ptx-content .problem-buttons {\n  display: flex;\n}\n\n.ptx-content .webwork-button {\n  @include buttons.ptx-button;\n}\n\n//.hidden-content used to be used for knowls and got repurposed for hiding webwork contents\n// now just used by webwork\n.problem-buttons.hidden-content,\n.problem-contents.hidden-content {\n  display: none;\n}\n", "// TODO - refactor\n\n.sagecell_sessionOutput pre {\n  font-family: var(--font-monospace);\n}\n\n.sagecell {\n  white-space: normal;\n  margin-top: 1.25em;\n  margin-bottom: 1.25em;\n}\n\n.sage-interact.sagecell {\n  margin: 0;\n}\n\n.sagecell_evalButton {\n  font-family: var(--font-body);\n  font-size: 16px;\n  padding: 0 0.65em;\n}\n\n.sagecell_evalButton {\n  cursor: pointer;\n  display: inline-block;\n  vertical-align: middle;\n  /* Disable accidental text-selection */\n  user-select: none;\n  /* Truncate overflowing text with ellipsis */\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  border-width: 1px;\n  border-style: solid;\n  font-weight: bold;\n  border-radius: 3px;\n}\n\n.sagecell_evalButton {\n  color: #383838;\n  background-image: linear-gradient(#f7f7f7, #bbbbbb);\n  border-color: #c4c4c4;\n}\n\n.sagecell_evalButton:hover {\n  color: #181868;\n  background-image: linear-gradient(#bbbbbb, #f7f7f7);\n}\n\n.sagecell_evalButton:focus,\n.sagecell_evalButton:active {\n  color: #20160b;\n  background-image: linear-gradient(#ff6852, #ffd7d1);\n  border-color: #ff2822;\n}\n\n.sagecell .sagecell_editor {\n  margin-bottom: 8px;\n}\n\n.sageanswer {\n  font-family: monospace;\n  white-space: pre;\n  margin-left: 3em;\n  margin-bottom: 2em;\n}\n\n.sageanswer .key {\n  display: inline-block;\n  vertical-align: top;\n  margin-right: 1em;\n}\n\n.sageanswer .output {\n  display: inline-block;\n  vertical-align: top;\n}\n", "// GeoGebra calculator\n\n$navbar-breakpoint: 856px !default;\n\n.calculator-container {\n  position: fixed;\n  z-index: 100;\n  bottom: 5px;\n  right: 5px;\n  width: 253px;\n  height: 460px;\n}\n\n@media screen and (max-width: $navbar-breakpoint) {\n  .calculator-container {\n    //assumes navbar moves to bottom of screen\n    bottom: 50px !important;\n  }\n}\n", "/*\n  Master list of color variables and default values.\n  Variables are defined in SCSS to allow for calculation of values. They are\n  then converted to CSS variables for use in the HTML so authors can, if\n  need be, override them with custom CSS.\n\n  Any new variable should be added to this file and either defined to another\n  variable or given a reasonable default value for the red-blue default theme.\n\n  Variables should be semantic, not descriptive\n  i.e. --link-color, not --pretty-blue\n*/\n\n@use \"sass:map\";\n\n// ==============================================================================\n// Light theme\n\n// ==============================================================================\n// Page structures\n\n$colors: (\n  // Background of page (gutters if any)\n  \"page-color\": white,\n  // Background of content area\n  \"content-background\": white,\n  // Border around content area - also possibly used for internal borders\n  \"page-border-color\": #ccc,\n\n  // ------------------------------------------------------------------------------\n  // Banner/nav related\n\n  \"doc-title-color\": #932919,\n  \"byline-color\": #333,\n  \"banner-background\": #fafafa,\n  \"navbar-background\": #ededed,\n  \"footer-background\": var(--banner-background),\n\n  // ------------------------------------------------------------------------------\n  // TOC related\n\n  \"toc-border-color\": #666,\n  \"toc-background\": var(--content-background),\n\n  \"tocitem-background\": var(--toc-background),\n  \"toc-text-color\": var(--body-text-color),\n\n  // highlight styles are used for hover\n  \"tocitem-highlight-background\": #671d12,\n  \"tocitem-highlight-text-color\": white,\n  \"tocitem-highlight-border-color\": var(--toc-border-color),\n  \n  // active styles are used for the current toc item\n  \"tocitem-active-background\": #671d12,\n  \"tocitem-active-text-color\": white,\n  \"tocitem-active-border-color\": var(--toc-border-color),\n\n  // level based colors for TOC\n  // levels are not necessarily all used\n  // see the toc-basics.scss for how these are determined\n  \"toclevel1-background\": var(--content-background),\n  \"toclevel1-text-color\": var(--toc-text-color),\n  \"toclevel2-background\": var(--content-background),\n  \"toclevel2-text-color\": var(--toc-text-color),\n  \"toclevel3-background\": var(--content-background),\n  \"toclevel3-text-color\": var(--toc-text-color),\n\n\n  // ==============================================================================\n  // Content\n  // ==============================================================================\n\n  // ------------------------------------------------------------------------------\n  // Text & titles\n\n  \"body-text-color\": #000,\n  \"body-title-color\": #000,\n\n  \"ptx-image-bg\": transparent,\n  \"activated-content-bg\": rgba(241, 185, 255, 30%),\n\n  \"summary-link-background\": var(--button-background),\n  \"summary-link-text-color\": var(--button-text-color),\n  \"summary-link-hover-background\": var(--button-hover-background),\n  \"summary-link-hover-text-color\": var(--button-hover-text-color),\n\n  // ------------------------------------------------------------------------------\n  // Links & knowls\n\n  \"link-text-color\": #2B5F82,\n  \"link-background\": transparent,\n  \"link-active-text-color\": var(--link-text-color),\n  \"link-active-background\": #cad2e1,\n\n  \"link-alt-text-color\": #A62E1C,\n  \"link-alt-background\": transparent,\n  \"link-alt-active-text-color\": var(--link-alt-text-color),\n  \"link-alt-active-background\": #e3d1ce,\n\n  \"knowl-link-color\": var(--link-text-color),\n  \"knowl-background\": #f5f8ff,\n  \"knowl-border-color\": #e0e9ff,\n  \"knowl-nested-1-background\": #f5f5ff,\n  \"knowl-nested-2-background\": #fffff5,\n  \"knowl-nested-3-background\": #f5ffff,\n  \"knowl-nested-4-background\": #fff5f5,\n\n  // ------------------------------------------------------------------------------\n  // Blocks\n\n  // Fall back generic block colors:\n  \"block-body-background\": var(--content-background),\n  \"block-border-color\": var(--knowl-border-color),\n  \"block-head-color\": var(--body-text-color),\n\n  // See below for specific block types\n  \n  \"aside-like-link-color\": var(--link-text-color),\n\n  // ------------------------------------------------------------------------------\n  // Buttons & Widgets\n\n  \"button-background\": #ededed,\n  \"button-text-color\": #333333,\n  \"button-border-color\": #ccc,\n  \"button-hover-background\": #c7c7c7,\n  \"button-hover-text-color\": var(--button-text-color),\n\n  \"dropdown-background\": var(--content-background),\n  \"dropdown-border-color\": var(--toc-border-color),\n  \"dropdown-text-color\": var(--toc-text-color),\n  \"dropdown-hover-background\": var(--tocitem-active-background),\n  \"dropdown-hover-text-color\": var(--tocitem-active-text-color),\n\n  // ------------------------------------------------------------------------------\n  // Other\n  \"code-background\": #fdfdfd,\n  \"code-inline-background\": #ededed,\n);\n\n// ==============================================================================\n// Block types\n\n// Variables for specific block types should look like those below. In this file\n// only \"top level\" blocks from the -like families are defined. \n// Other themes/color palettes may define\n// more specific ones - see palette_quad_chunks.scss for an example.\n\n// block-types based on those in entities.ent\n$block-types: \"assemblage-like\", \"definition-like\", \"theorem-like\", \"theorem-like\", \"axiom-like\", \"remark-like\", \"computation-like\", \"openproblem-like\", \"aside-like\", \"proof-like\", \"example-like\", \"project-like\", \"goal-like\", \"solution-like\";\n// TODO - \"proof\" should probably be updated to \"proof-like\" in HTML css\n\n@each $block in $block-types {\n  $colors: map.merge(\n    $colors,\n    (\n      // define background and border, but default to generic block colors\n      \"#{$block}-body-background\": var(--block-body-background),\n      \"#{$block}-border-color\": var(--block-border-color),\n    )\n  );\n}\n", "// This file contains functions and mixins for working with colors in SCSS\n\n@use \"sass:map\";\n@use \"sass:color\";\n\n@mixin set-root-colors($colors, $dark-colors: null) {\n  :root {\n    color-scheme: light;\n    // prevent variable leak through to dark\n    &:not(.dark-mode) {\n      @include scss-to-css($colors);\n    }\n  }\n\n  @if $dark-colors {\n    :root.dark-mode {\n      color-scheme: dark;\n      @include scss-to-css($dark-colors);\n    }\n  }\n}\n\n// Renders a map of SCSS variables as CSS variables\n@mixin scss-to-css($colors) {\n  @each $name, $value in $colors {\n    --#{$name}: #{$value};\n  }\n}\n\n// Create a map of colors that blend $color with $other at $mix-amounts\n// The resulting map will have keys of the form 'color-other-10'\n// Indicating 10% of other mixed into color\n@function mixes($color, $other, $mix-amounts) {\n  $result: ();\n\n  @each $i in $mix-amounts {\n    $result: map.set($result, '#{$color}-#{$other}-#{$i}', 'color-mix(in oklab, var(--#{$color}), #{$other} #{$i}%)');\n  }\n\n  @return $result;\n}\n\n$std-mixes: (1, 2, 3, 4, 5, 10, 15, 20, 25, 30, 35, 40, 50, 60, 65, 70, 75, 80, 85, 90, 95, 96, 97, 98, 99);\n\n// Creates a map of color blends for a given color\n// By default it creates blends with black, white, and gray at $std-mixes amounts\n// Mixing is done using css color-mix function so that if a theme file has the base\n// css variable overridden, the blends will be updated accordingly\n@function get-blends($color, $shades: $std-mixes, $tints: $std-mixes, $tones: $std-mixes, ) {\n  $shades: mixes($color, black, $std-mixes);\n  $tints: mixes($color, white, $std-mixes);\n  $tones: mixes($color, gray, $std-mixes);\n\n  $blends: map.merge(\n    $tints,\n    $shades\n  );\n\n  $blends: map.merge(\n    $blends,\n    $tones\n  );\n  @return $blends;\n}\n\n//--------------------------------------------------------------------------\n// https://jonnykates.medium.com/automating-colour-contrast-ratios-with-sass-e201f3b52797\n// Formula there has a typo, need parens around the sum of the three color channels\n\n@function text-contrast($color, $light: #ffffff, $dark: #000000) {\n  $color-brightness: round(\n    (\n      (color.red($color) * 299) +\n      (color.green($color) * 587) +\n      (color.blue($color) * 114)\n    ) / 1000\n  );\n\n  $light-color: round(\n    (\n      (color.red(#ffffff) * 299) +\n      (color.green(#ffffff) * 587) +\n      (color.blue(#ffffff) * 114)\n    ) / 1000\n  );\n\n  @if abs($color-brightness) < calc($light-color / 2){\n    @return $light;\n  } @else {\n    @return $dark;\n  }\n}\n\n// @debug \"text-contrast(#7b7b55) should be #ffffff: \" text-contrast(#7b7b55);\n// @debug \"text-contrast(#9b9b70) should be #000000: \" text-contrast(#9b9b70);\n// @debug \"text-contrast(#766f7a) should be #ffffff: \" text-contrast(#766f7a);\n// @debug \"text-contrast(#70909b) should be #000000: \" text-contrast(#70909b);\n//--------------------------------------------rgb(25, 25, 24)-----------------------\n"],
